// === Tab: mySketch ===
let cols;
let rows;
float[][] current;
float[][] previous;

let dampening = 0.95;

function setup() {
  createCanvas(600, 600);
  cols = width;
  rows = height;
  current = new Array(cols)[rows];
  previous = new Array(cols)[rows];
}

function mouseDragged() {
  previous[(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))][(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))] = 255;
}

function draw() {
  background(0);

  loadPixels();
  for (i = 1; i < cols-1; i++) {
    for (j = 1; j < rows-1; j++) {
      current[i][j] = (
        previous[i-1][j] + 
        previous[i+1][j] +
        previous[i][j-1] + 
        previous[i][j+1]) / 2 -
        current[i][j];
      current[i][j] = current[i][j] * dampening;
      let index = i + j * cols;
      pixels[index] = color(current[i][j]);
    }
  }
  updatePixels();

  float[][] temp = previous;
  previous = current;
  current = temp;
}

